  "Ano de lançamento, gênero, região, posição (rota), classe, espécie e alcance (corpo a corpo ou à distância). Alguns campeões têm mais de uma posição, classe ou espécie.": "Erscheinungsjahr, Geschlecht, Region, Position (Lane), Klasse, Spezies und Reichweite (Nahkampf oder Fernkampf). Manche Champions haben mehr als eine Position, Klasse oder Spezies.",
  "Você tem {n} tentativas. Só valem nomes de campeões: comece a digitar e escolha na lista. Uma vez por dia, a qualquer momento, dá para pedir uma dica, que revela uma característica que você ainda não acertou. A dica gasta uma tentativa. Um campeão novo aparece todo dia à meia-noite (horário de Brasília), diferente para cada jogador.": "Du hast {n} Versuche. Nur Champion-Namen zählen: Beginne zu tippen und wähle aus der Liste. Einmal pro Tag kannst du jederzeit einen Hinweis anfordern, der ein Merkmal verrät, das du noch nicht erraten hast. Ein Hinweis kostet einen Versuch. Jeden Tag um Mitternacht (Brasília-Zeit) erscheint ein neuer Champion, für jeden Spieler ein anderer.",
