  "A moeda do Rift Arcade. Você ganha moedas com códigos de recompensa e, no futuro, poderá usá-las para trocar por efeitos, ícones e outras novidades.": "Die Währung von Rift Arcade. Du bekommst Münzen mit Belohnungscodes und kannst sie in Zukunft gegen Effekte, Symbole und andere Neuigkeiten eintauschen.",
