  "Como ganhar abóboras": "So sammelst du Kürbisse",
  "Você ganha abóboras jogando: cada partida concluída, em qualquer jogo, rende abóboras.": "Du verdienst Kürbisse durch Spielen: Jede beendete Partie in jedem Spiel bringt Kürbisse.",
  "No Na Medida, o Diário e a Ranqueada rendem abóboras pelo dia completo (as 5 rodadas); no modo Livre, a cada 5 rodadas.": "Bei Na Medida bringen Täglich und Ranglisten-Modus Kürbisse für den ganzen Tag (die 5 Runden); im freien Modus alle 5 Runden.",
  "Dá para ganhar até {num} abóboras por dia. O limite zera à meia-noite (horário de Brasília).": "Du kannst bis zu {num} Kürbisse pro Tag verdienen. Das Limit wird um Mitternacht (Brasília-Zeit) zurückgesetzt.",
  "A cada {num} abóboras você sobe um nível e libera a recompensa dele.": "Alle {num} Kürbisse steigst du eine Stufe auf und schaltest ihre Belohnung frei.",
