  "Pagamento recebido! Suas Rift Coins chegam em instantes.": "Zahlung erhalten! Deine Rift Coins kommen in Kürze an.",
  "Pagamento pendente. As Rift Coins chegam assim que for confirmado.": "Zahlung ausstehend. Die Rift Coins kommen an, sobald sie bestätigt ist.",
  "O pagamento não foi concluído.": "Die Zahlung wurde nicht abgeschlossen.",
  "nível do passe": "Stufe des Passes",
  "✓ Completo": "✓ Abgeschlossen",
  "★ Premium": "★ Premium",
  "Grátis": "Kostenlos",
  "✓ Resgatado": "✓ Eingelöst",
  "Termine partidas para ganhar abóboras e encher a barra: ao completá-la, você sobe de nível e libera a recompensa dele. Cada partida concluída, ranqueada ou não, rende abóboras (há um limite por dia, que zera à meia-noite, horário de Brasília).": "Beende Partien, um Kürbisse zu sammeln und die Leiste zu füllen: Ist sie voll, steigst du auf und schaltest die Belohnung dieser Stufe frei. Jede beendete Partie, ob gewertet oder nicht, bringt Kürbisse (es gibt ein Tageslimit, das um Mitternacht Brasília-Zeit zurückgesetzt wird).",
  "Entre na sua conta para participar do passe de batalha.": "Melde dich an, um am Battle Pass teilzunehmen.",
  "O passe de batalha precisa de conexão com o servidor do site, que não está disponível nesta versão.": "Der Battle Pass braucht eine Verbindung zum Server der Seite, die in dieser Version nicht verfügbar ist.",
