  "Adversário": "Gegner",
  "Você": "Du",
  "Meio": "Mitte",
  "Dragão Elemental": "Elementardrache",
  "Ótimo!": "Sehr gut!",
  "Bom": "Gut",
  "Passou longe": "Weit daneben",
  "Cedo demais": "Zu früh",
  "Tarde demais": "Zu spät",
  "Objetivo garantido!": "Ziel gesichert!",
  "O objetivo sobreviveu!": "Das Ziel hat überlebt!",
  "Roubaram o objetivo!": "Das Ziel wurde gestohlen!",
  "Desafio de timing · League of Legends": "Timing-Challenge · League of Legends",
  "Um objetivo está quase morrendo e o time inimigo está de olho. Use o <b>Golpear</b> na hora certa para <b>garantir o objetivo</b>: os pontos dependem de quão rápido você golpeia depois que a vida do objetivo entra no dano do Golpear.": "Ein Ziel steht kurz vor dem Tod und das gegnerische Team lauert. Nutze <b>Zerschmettern</b> im richtigen Moment, um dir das <b>Ziel zu sichern</b>: Die Punkte hängen davon ab, wie schnell du zuschlägst, nachdem die Lebenspunkte des Ziels in den Schaden von Zerschmettern gefallen sind.",
  "Observe": "Beobachte",
  "A vida do objetivo cai com o dano dos aliados e dos adversários, inclusive o seu. Cada time tem topo, selva, meio e atirador, e você é o selva do time azul.": "Die Lebenspunkte des Ziels sinken durch den Schaden von Verbündeten und Gegnern, deinen eingeschlossen. Jedes Team hat Top, Dschungel, Mitte und Schütze, und du bist der Dschungler des blauen Teams.",
  "Golpeie": "Schlage zu",
  "O Golpear mata se a vida for menor ou igual ao dano dele (600, 900 ou 1200 baseado no nível). Se errar, a rodada continua: se o seu time ficar com o objetivo vale 25 pontos; se for o time inimigo, 0.": "Zerschmettern tötet, wenn die Lebenspunkte kleiner oder gleich seinem Schaden sind (600, 900 oder 1.200, je nach Level). Bei einem Fehlschlag geht die Runde weiter: Sichert sich dein Team das Ziel, gibt es 25 Punkte; das gegnerische Team, 0.",
  "O botão Q do seu campeão também machuca o objetivo. Use para finalizar ou combar com o Golpear.": "Die Q-Taste deines Champions verletzt das Ziel ebenfalls. Nutze sie zum Erledigen oder als Kombo mit Zerschmettern.",
  "As {rodadas} rodadas formam uma partida, com os mesmos campeões do início ao fim. Até <b>100 pontos</b> por rodada. Teclas: <b>F</b> ou <b>Espaço</b> = Golpear · <b>Q</b> = habilidade.": "Die {rodadas} Runden bilden eine Partie mit denselben Champions von Anfang bis Ende. Bis zu <b>100 Punkte</b> pro Runde. Tasten: <b>F</b> oder <b>Leertaste</b> = Zerschmettern · <b>Q</b> = Fähigkeit.",
  "Seu recorde: <b>{n}</b> pontos": "Dein Rekord: <b>{n}</b> Punkte",
  "JOGAR": "SPIELEN",
  "Rodada {n} de {total}": "Runde {n} von {total}",
  "Rodada {n}": "Runde {n}",
  "Você é o selva do time azul": "Du bist der Dschungler des blauen Teams",
  "Q: toque para a Onda Sônica; em até {janela}s toque de novo para o Chute, que bate mais quanto menos vida o objetivo tem. Recarga {seg}s.": "Q: tippen für Schallwelle; innerhalb von {janela} s erneut tippen für den Tritt, der härter trifft, je weniger Leben das Ziel hat. Abklingzeit {seg} s.",
  "Q: toque rápido para uma estocada ({dano}); segurando, causa mais dano.": "Q: kurz tippen für einen Stoß ({dano}); gehalten verursacht er mehr Schaden.",
  "Q: arma o seu próximo ataque (até {janela}s) com +{dano} de dano; cada golpe seu corta 0,5s da recarga. Recarga {seg}s.": "Q: lädt deinen nächsten Angriff (bis zu {janela} s) mit +{dano} Schaden auf; jeder deiner Treffer verkürzt die Abklingzeit um 0,5 s. Abklingzeit {seg} s.",
  "Q: {dano} de dano. Recarga {seg}s.": "Q: {dano} Schaden. Abklingzeit {seg} s.",
  "Ataque armado! O seu próximo golpe causa dano extra.": "Angriff geladen! Dein nächster Treffer verursacht Zusatzschaden.",
  "Perdeu a janela do segundo Q: a recarga começou.": "Das Zeitfenster für das zweite Q ist vorbei: Abklingzeit läuft.",
  "Segurou demais! A recarga é a metade.": "Zu lange gehalten! Die Abklingzeit ist halbiert.",
  "Você está no nível <b>{nivel}</b>: o dano do seu Golpear é de <b>{smite}</b>. Golpeie quando a vida do {obj} for <b>menor ou igual</b> a esse valor, o mais perto possível.": "Du bist Level <b>{nivel}</b>: Dein Zerschmettern verursacht <b>{smite}</b> Schaden. Schlage zu, wenn die Lebenspunkte von {obj} <b>kleiner oder gleich</b> diesem Wert sind, so nah wie möglich.",
  "Golpeie o {obj} com o Golpear no momento certo!": "Nutze Zerschmettern auf {obj} im genau richtigen Moment!",
  "Você golpeou <b>{seg}s</b> depois de a vida do {obj} entrar no dano do Golpear ({smite}).": "Du hast <b>{seg} s</b>, nachdem die Lebenspunkte von {obj} in den Schaden von Zerschmettern ({smite}) gefallen sind, zugeschlagen.",
  "Ele ainda tinha <b>{vida}</b> de vida, <b>{faltou}</b> acima do dano do Golpear ({smite}). O time inimigo levou o objetivo.": "Es hatte noch <b>{vida}</b> Lebenspunkte, <b>{faltou}</b> über dem Schaden von Zerschmettern ({smite}). Das gegnerische Team hat sich das Ziel geholt.",
  "O {obj} morreu antes do seu Golpear.": "{obj} ist vor deinem Zerschmettern gestorben.",
  "A sua habilidade derrubou o {obj} antes do Golpear. Só o Golpear garante o objetivo!": "Deine Fähigkeit hat {obj} vor Zerschmettern erledigt. Nur Zerschmettern sichert das Ziel!",
  "O time inimigo levou o {obj}: o golpe final foi de {quem}.": "Das gegnerische Team hat sich {obj} geholt: den letzten Treffer landete {quem}.",
  "Seu time derrubou o {obj} antes do seu Golpear (golpe final de {quem}).": "Dein Team hat {obj} vor deinem Zerschmettern erledigt (letzter Treffer von {quem}).",
  "Total: <b>{n}</b> pontos": "Gesamt: <b>{n}</b> Punkte",
