  "Cuidado": "Vorsicht",
  "O Caçador inimigo também usa Golpear quando a vida do objetivo estiver perto do dano do Golpear.": "Der gegnerische Dschungler nutzt ebenfalls Zerschmettern, wenn die Lebenspunkte des Ziels nahe am Schaden von Zerschmettern liegen.",
  "Seu time ficou com o objetivo!": "Dein Team hat sich das Ziel geholt!",
  "Seu time levou o objetivo": "Dein Team hat das Ziel geholt",
  "Seu Golpear foi cedo demais (<b>{vida}</b> de vida, <b>{faltou}</b> acima do dano do Golpear), mas seu time ficou com o {obj} (golpe final de {quem}).": "Dein Zerschmettern kam zu früh (<b>{vida}</b> Lebenspunkte, <b>{faltou}</b> über dem Schaden von Zerschmettern), aber dein Team hat sich {obj} geholt (letzter Treffer von {quem}).",
  "A sua habilidade finalizou o {obj} antes do Golpear: o objetivo ficou com o seu time.": "Deine Fähigkeit hat {obj} vor Zerschmettern erledigt: Das Ziel ging an dein Team.",
  "O selva inimigo ({quem}) usou o Golpear e levou o {obj}.": "Der gegnerische Dschungler ({quem}) hat Zerschmettern genutzt und sich {obj} geholt.",
  "Seu Golpear tinha sido cedo demais: o objetivo ainda tinha <b>{vida}</b> de vida.": "Dein Zerschmettern kam zu früh: Das Ziel hatte noch <b>{vida}</b> Lebenspunkte.",
  "Golpear Inimigo": "Gegnerisches Zerschmettern",
  "Cedo demais! Seu Golpear foi desperdiçado, mas a rodada continua.": "Zu früh! Dein Zerschmettern ist verpufft, aber die Runde geht weiter.",
  "seu time": "dein Team",
  "◆ Minigames do universo de LoL": "◆ Minispiele aus dem LoL-Universum",
  "Jogos rápidos e uma carreira inteira para jogar. Entre com sua conta e cada partida, recorde e progresso fica guardado, em qualquer aparelho.": "Schnelle Spiele und eine ganze Karriere zum Spielen. Melde dich an und jede Partie, jeder Rekord und dein Fortschritt werden gespeichert, auf jedem Gerät.",
