  "Crie seu jogador aos 16 anos e leve a carreira da base ao Mundial.": "Erstelle deinen Spieler mit 16 und führe seine Karriere von der Nachwuchsakademie bis zur Weltmeisterschaft.",
  "Jogar": "Spielen",
