  "Modo": "Modus",
  "Só os nomes: os OVRs aparecem quando o time estiver completo.": "Nur die Namen: Die OVRs erscheinen, wenn das Team komplett ist.",
  "Vale PDR na ranqueada": "Bringt RP in der Rangliste",
  "(as 3 primeiras do dia; cada uma vale o seu PDR).": "(die ersten 3 des Tages; jede bringt ihre eigenen RP).",
  "(as 2 primeiras do dia; cada uma vale o seu PDR).": "(die ersten 2 des Tages; jede bringt ihre eigenen RP).",
  "Os OVRs aparecem durante a escolha. Modo para treinar:": "Die OVRs werden während der Auswahl angezeigt. Trainingsmodus:",
  "não vale ranqueada": "zählt nicht für die Rangliste",
  "Role o dado: sai um time de algum split do CBLOL. Escolha um jogador (ou o técnico) dele e role de novo até completar o seu time.": "Würfle: Es erscheint ein Team aus einem CBLOL-Split. Wähle einen seiner Spieler (oder den Trainer) und würfle erneut, bis dein Team komplett ist.",
