  "Apaga a conta, o nome de usuário, o progresso salvo e todo o histórico. Não dá para desfazer.": "Löscht das Konto, den Benutzernamen, den gespeicherten Fortschritt und den gesamten Verlauf. Das kann nicht rückgängig gemacht werden.",
