  ", o progresso salvo e todo o histórico de partidas. Não dá para desfazer.": ", den gespeicherten Fortschritt und den gesamten Partienverlauf. Das kann nicht rückgängig gemacht werden.",
  "Para confirmar, digite o seu nome de usuário:": "Gib zur Bestätigung deinen Benutzernamen ein:",
