  "Ninguém na ranqueada ainda. Seja o primeiro!": "Noch niemand in der Rangliste. Sei der Erste!",
  "Entre na sua conta e todos os jogos passam a valer PDR para subir do Ferro ao Desafiante.": "Melde dich an und alle Spiele bringen RP, um von Eisen bis Herausforderer aufzusteigen.",
  "Entrar para jogar a ranqueada": "Anmelden, um die Rangliste zu spielen",
  "Entre na conta para jogar a ranqueada": "Melde dich an, um die Rangliste zu spielen",
  "Como funciona": "So funktioniert es",
  "Partidas do dia:": "Tagespartien:",
  "as primeiras partidas do dia valem PDR, com a conta conectada. Em alguns jogos vale só a primeira, em outros as 2 primeiras.": "Die ersten Partien des Tages bringen RP, wenn du angemeldet bist. In manchen Spielen zählt nur die erste, in anderen die ersten 2.",
  "+1 Pinstouro (pulo) por partida (3 no total)": "+1 Pinstouro (Überspringen) pro Partie (insgesamt 3)",
  "você pode escolher o caçador": "du kannst deinen Jungler wählen",
  "Valem para a ranqueada, com a conta conectada:": "Diese zählen für die Rangliste, wenn du angemeldet bist:",
  "(só o modo Oculto),": "(nur im versteckten Modus),",
  "e": "und",
  "Elos:": "Ränge:",
  "Ferro, Bronze, Prata, Ouro, Platina, Esmeralda e Diamante, com 3 divisões cada. Ao alcançar 100 PDR, você avança para a próxima divisão.": "Eisen, Bronze, Silber, Gold, Platin, Smaragd und Diamant mit jeweils 3 Divisionen. Bei 100 RP steigst du in die nächste Division auf.",
  "Mestre, Grão-Mestre e Desafiante:": "Meister, Großmeister und Herausforderer:",
  "depois do Diamante 1 vem o Mestre. Todo dia à meia-noite, pela ordem de PDR, os 100 melhores com 500+ PDR viram Desafiante e os 200 seguintes com 200+ PDR, Grão-Mestre.": "Nach Diamant 1 kommt Meister. Jeden Tag um Mitternacht werden nach RP-Reihenfolge die besten 100 mit 500+ RP zu Herausforderern und die nächsten 200 mit 200+ RP zu Großmeistern.",
  "Queda:": "Abstieg:",
  "perdendo PDR, a divisão desce até 0. Perdendo com 0, volta para a divisão anterior com 75 PDR. Ferro 3 não cai.": "Wenn du RP verlierst, sinkt die Division bis auf 0. Bei einer Niederlage mit 0 geht es zurück in die vorherige Division mit 75 RP. Eisen 3 steigt nicht ab.",
  "Páginas do ranking": "Ranglistenseiten",
