  ", pela pontuação da partida (de 10 a 100):": ", nach der Punktzahl der Partie (von 10 bis 100):",
  "Desafio do Golpear:": "Zerschmettern-Challenge:",
  ", pela nota da partida (soma das 5 rodadas, de 0 a 500):": ", nach der Punktzahl der Partie (Summe der 5 Runden, von 0 bis 500):",
  ". Entre esses pontos o PDR varia proporcionalmente. Começou e não terminou até a meia-noite:": ". Zwischen diesen Punkten verläuft der PDR proportional. Begonnen, aber bis Mitternacht nicht beendet:",
