  "por partida.": "pro Partie.",
  "Inatividade:": "Inaktivität:",
  "do Ouro para cima, depois de 3 dias sem jogar, perde 25 PDR por dia parado (até no máximo o Ouro 3 com 0 PDR). Qualquer partida de qualquer jogo conta como atividade.": "Ab Gold aufwärts verlierst du nach 3 Tagen ohne Spiel 25 RP pro inaktivem Tag (höchstens bis Gold 3 mit 0 RP). Jede Partie in jedem Spiel zählt als Aktivität.",
