  "Lendas do CBLOL e Campeão Oculto:": "CBLOL-Legenden und Versteckter Champion:",
  "+1 dado bônus (3 no total) e +1 tentativa no Campeão Oculto (9 no total)": "+1 Bonuswürfel (insgesamt 3) und +1 Versuch im versteckten Champion (insgesamt 9)",
  "Ranking · Rift Arcade": "Rangliste · Rift Arcade",
  "Ranqueada do Rift Arcade: todos os jogos valem PDR. Ranking geral por elo, do Ferro ao Desafiante, e rankings diário, semanal e mensal.": "Rift-Arcade-Rangliste: Alle Spiele bringen RP. Gesamtrangliste nach Rang, von Eisen bis Herausforderer, sowie Tages-, Wochen- und Monatsranglisten.",
  "Vale 1 partida por dia, com o quebra-cabeça sorteado no servidor.": "Zählt 1 Partie pro Tag, das Rätsel wird auf dem Server ausgelost.",
  "No máximo 3 erros: o 4º erro perde a partida (−20 PDR).": "Höchstens 3 Fehler: der 4. Fehler beendet die Partie als Niederlage (−20 RP).",
  "Pela pontuação: perfeito = +30, 1 dica = +22, 1 erro = +15, 2 erros = +5, 3 erros = −10.": "Nach Punktzahl: perfekt = +30, 1 Hinweis = +22, 1 Fehler = +15, 2 Fehler = +5, 3 Fehler = −10.",
