  "ENTER": "ENTER",
  "Descubra a sua palavra do dia em 6 tentativas (cada jogador tem uma palavra diferente). Todas as respostas são nomes do universo de League of Legends: campeões, regiões e lugares de Runeterra, itens, monstros do mapa e personagens da lore.": "Finde dein Wort des Tages in 6 Versuchen (jeder Spieler hat ein anderes Wort). Alle Antworten sind Namen aus dem League-of-Legends-Universum: Champions, Regionen und Orte Runeterras, Gegenstände, Monster der Karte und Figuren der Lore.",
  "A palavra do dia pode ter de 5 a 7 letras. Depois de cada tentativa, as peças mostram o quão perto você está.": "Das Wort des Tages kann 5 bis 7 Buchstaben haben. Nach jedem Versuch zeigen die Felder, wie nah du dran bist.",
  "Toque num quadrado para escolher onde escrever: dá para preencher primeiro as letras que você já sabe, em qualquer posição.": "Tippe auf ein Feld, um zu wählen, wo du schreibst: du kannst zuerst die Buchstaben eintragen, die du schon kennst, an jeder Position.",
  "A letra": "Der Buchstabe",
  "está na palavra e no lugar certo.": "ist im Wort und an der richtigen Stelle.",
  "está na palavra, mas em outro lugar.": "ist im Wort, aber an einer anderen Stelle.",
  "não está na palavra.": "ist nicht im Wort.",
  "Vale tentar qualquer palavra comum do português ou do universo de LoL com o mesmo número de letras. Acentos e apóstrofos são preenchidos sozinhos e não contam nas dicas. As palavras podem ter letras repetidas.": "Du kannst jedes gebräuchliche portugiesische Wort oder Wort aus dem LoL-Universum mit derselben Buchstabenanzahl versuchen. Akzente und Apostrophe werden automatisch ergänzt und zählen bei den Hinweisen nicht. Wörter können Buchstaben mehrfach enthalten.",
  "Uma palavra nova aparece todo dia à meia-noite (horário de Brasília).": "Jeden Tag um Mitternacht erscheint ein neues Wort (Brasília-Zeit).",
  "Ranqueada:": "Rangliste:",
  "com a conta conectada, a partida vale PDR. Começou e não terminou até a meia-noite conta como erro.": "Mit angemeldetem Konto bringt die Partie RP. Begonnen, aber bis Mitternacht nicht beendet, zählt als Fehlschlag.",
