  "Brilhos nas barras, estrelas, cartões e avisos. Desligue se o jogo ficar pesado ou se preferir uma tela mais calma.": "Leuchteffekte an Balken, Sternen, Karten und Hinweisen. Schalte sie aus, wenn das Spiel ruckelt oder du eine ruhigere Oberfläche bevorzugst.",
