  "Dê nome ao seu time, escolha a sigla e monte o ícone (um símbolo com as suas cores, ou só a escrita do nome). Você recebe créditos e, na próxima etapa, escolhe seus 5 primeiros jogadores entre 15 opções para começar na {x1}. A aparência não dá vantagem na competição.": "Gib deinem Team einen Namen, wähle das Kürzel und gestalte das Symbol (ein Symbol in deinen Farben oder nur der Name als Schrift). Du erhältst Credits und wählst im nächsten Schritt deine ersten 5 Spieler aus 15 Optionen, um in der {x1} zu starten. Das Aussehen verschafft keinen Vorteil im Wettbewerb.",
