  "Você não tem anúncios abertos. Para vender um jogador, abra a ficha dele em Meu elenco e toque em Anunciar.": "Du hast keine offenen Angebote. Um einen Spieler zu verkaufen, öffne sein Profil unter Mein Kader und tippe auf Anbieten.",
