  "🏆 Campeão": "🏆 Champion",
  "Chaveamento": "Turnierbaum",
  "16 equipes (técnicos classificados e equipes do sistema). De segunda a sexta, 2 jogos por dia contra equipes diferentes (melhor de 1). Os 4 melhores jogam as semifinais no sábado (melhor de 3) e a final no domingo (melhor de 5). Contra a equipe de outro técnico você joga contra o bot dela, e cada um conta o próprio resultado. O campeão ganha vaga no {x1}.": "16 Teams (qualifizierte Trainer und Systemteams). Montag bis Freitag 2 Spiele pro Tag gegen verschiedene Teams (Best of 1). Die besten 4 spielen am Samstag die Halbfinals (Best of 3) und am Sonntag das Finale (Best of 5). Gegen das Team eines anderen Trainers spielst du gegen dessen Bot, und jeder zählt sein eigenes Ergebnis. Der Champion erhält einen Platz im {x1}.",
  "16 equipes em 4 grupos de 4, sorteados por potes de poder. Segunda: treino. Terça a quinta: 2 jogos por dia contra o seu grupo (cada adversário duas vezes). Sexta: quartas de final (melhor de 3) com os 2 primeiros de cada grupo; sábado, semifinais (melhor de 3); domingo, a final (melhor de 5).": "16 Teams in 4 Gruppen à 4, ausgelost nach Stärke-Töpfen. Montag: Training. Dienstag bis Donnerstag: 2 Spiele pro Tag gegen deine Gruppe (jeder Gegner zweimal). Freitag: Viertelfinale (Best of 3) mit den ersten 2 jeder Gruppe; Samstag Halbfinale (Best of 3); Sonntag das Finale (Best of 5).",
  "Os 2 primeiros sobem para a {x1}; os demais continuam na {x2}.": "Die ersten 2 steigen in die {x1} auf; die übrigen bleiben in der {x2}.",
  "Os 2 primeiros ganham vaga na {x1}{x2}. Não há rebaixamento.": "Die ersten 2 erhalten einen Platz im {x1}{x2}. Es gibt keinen Abstieg.",
