  "{x8} campeões favoritos": "{x8} Lieblings-Champions haben",
  ". Quanto mais ele joga com um campeão, mais maestria ganha: a cada mapa são {x9} pontos na vitória e {x10} na derrota. Com {x11} pontos ele entra na lista de favoritos e, ao jogar com o campeão, ganha um bônus de Poder que cresce com o nível ({x12}).": ". Je öfter er einen Champion spielt, desto mehr Meisterschaft sammelt er: Jede Karte bringt {x9} Punkte für einen Sieg und {x10} für eine Niederlage. Mit {x11} Punkten kommt er auf die Favoritenliste und erhält beim Spielen dieses Champions einen Stärkebonus, der mit dem Level wächst ({x12}).",
  "Nenhum campeão com esses filtros.": "Keine Champions mit diesen Filtern.",
  "Personalizar a organização": "Organisation anpassen",
  "Só a aparência muda. O nome e a sigla não podem ser alterados e nada aqui dá vantagem na competição.": "Nur das Aussehen ändert sich. Name und Kürzel können nicht geändert werden, und nichts hier verschafft einen Vorteil im Wettbewerb.",
