  "Duas partidas por dia e a disputa pelo troféu da liga. Na {x7}, os 2 primeiros ganham vaga {x8}; na {x9}, os 2 primeiros sobem de divisão.": "Zwei Spiele pro Tag und der Kampf um die Liga-Trophäe. In der {x7} erhalten die ersten 2 einen Platz {x8}; in der {x9} steigen die ersten 2 auf.",
