  "Requisito:": "Voraussetzung:",
  "2 primeiros da {x8} na semana 1 (ou na semana 4 da temporada anterior).": "Die ersten 2 der {x8} in Woche 1 (oder in Woche 4 der Vorsaison).",
  "Formato:": "Format:",
  "16 equipes. Segunda a sexta: 2 jogos por dia contra equipes diferentes (melhor de 1). Sábado: semifinais com os 4 melhores (melhor de 3). Domingo: final (melhor de 5). O campeão ganha vaga no {x9}.": "16 Teams. Montag bis Freitag: 2 Spiele pro Tag gegen verschiedene Teams (Best of 1). Samstag: Halbfinale mit den besten 4 (Best of 3). Sonntag: Finale (Best of 5). Der Champion erhält einen Platz im {x9}.",
  "Semana 4 · {x13} a {x14}": "Woche 4 · {x13} bis {x14}",
  "2 primeiros da {x17} na semana 2 ou 3, ou campeão da {x18}.": "Die ersten 2 der {x17} in Woche 2 oder 3 oder Champion der {x18}.",
  "16 equipes em 4 grupos. Segunda: treino (2 jogos, sem pontos, só XP e Maestria). Terça a quinta: 2 jogos por dia no grupo (cada adversário duas vezes). Sexta: quartas (melhor de 3). Sábado: semifinais (melhor de 3). Domingo: final (melhor de 5).": "16 Teams in 4 Gruppen. Montag: Training (2 Spiele, keine Punkte, nur XP und Meisterschaft). Dienstag bis Donnerstag: 2 Spiele pro Tag in der Gruppe (jeder Gegner zweimal). Freitag: Viertelfinale (Best of 3). Samstag: Halbfinale (Best of 3). Sonntag: Finale (Best of 5).",
  "Liga Academy / Liga Nacional": "Academy-Liga / Nationale Liga",
  "Vice": "Vizemeister",
  "Semifinalistas": "Halbfinalisten",
  "{x1} sai do seu elenco e volta ao mercado{x2}.": "{x1} verlässt deinen Kader und kehrt auf den Markt zurück{x2}.",
  "(o Legado continua disponível nos baús)": "(der Vermächtnis-Spieler bleibt in Truhen verfügbar)",
  "As {x1} estrela(s) de evolução dele se perdem{x2}.": "Seine {x1} Entwicklungsstern(e) gehen verloren{x2}.",
  "; metade dos {x1} fragmentos gastos nelas volta para você": "; die Hälfte der dafür ausgegebenen {x1} Fragmente erhältst du zurück",
  "As {x1} cópia(s) repetida(s) dele viram fragmentos: {x2} ({x3} por cópia).": "Seine {x1} doppelte(n) Kopie(n) werden zu Fragmenten: {x2} ({x3} pro Kopie).",
  "Esta ação não pode ser desfeita.": "Diese Aktion kann nicht rückgängig gemacht werden.",
  "Só cópias repetidas": "Nur doppelte Kopien",
  "Quer se desfazer de algumas cópias e continuar com o jogador? Cada cópia rende {x1} fragmentos.": "Möchtest du einige Kopien loswerden und den Spieler behalten? Jede Kopie bringt {x1} Fragmente.",
