  "Ele vai para o seu inventário. Para escalá-lo como titular você efetiva um contrato (1 semana ou 1 temporada) com salário em créditos.": "Er kommt in dein Inventar. Um ihn als Stammspieler aufzustellen, aktivierst du einen Vertrag (1 Woche oder 1 Saison) mit Gehalt in Credits.",
