  "Esse jogador é titular. Se ele for vendido, a vaga é preenchida por um reserva ou por um substituto fraco.": "Dieser Spieler ist Stammspieler. Wird er verkauft, wird der Platz durch einen Ersatzspieler oder einen schwachen Ersatz besetzt.",
