  "Escalar {x1}": "{x1} aufstellen",
  "Escolha a vaga. Quem estiver nela vai para a reserva. Jogar fora da posição principal reduz a eficiência do jogador em {x2}% e trocar titulares reduz a sinergia.": "Wähle den Platz. Wer dort steht, wandert auf die Ersatzbank. Außerhalb der Hauptposition zu spielen senkt die Effizienz des Spielers um {x2} %, und Wechsel der Stammspieler senken die Synergie.",
