  "Garantia: um {x1} a cada {x2} baús ({x3}/{x4}).": "Garantie: ein {x1} alle {x2} Truhen ({x3}/{x4}).",
  "Desafie outro time para uma partida de treino (scrim) de verdade: picks e bans, depois a simulação com os campeões. Não vale pontos de campeonato. Você pode jogar quantos quiser por dia, mas só os": "Fordere ein anderes Team zu einem echten Trainingsspiel (Scrim) heraus: Picks und Bans, danach die Simulation mit den Champions. Es zählt nicht für Wettbewerbspunkte. Du kannst pro Tag beliebig viele spielen, aber nur die",
  "dão XP para os seus titulares (": "geben deinen Stammspielern XP (",
  "); os demais não contam para nada.": "); alle weiteren zählen für nichts.",
  "Recrute jogadores Legado, ídolos reais do cenário competitivo, e leve a sua equipe ao topo do mundo.{x4}": "Rekrutiere Vermächtnis-Spieler, echte Idole der Wettkampfszene, und führe dein Team an die Weltspitze.{x4}",
