  "{x2} patrocinador(es) ativo(s)": "{x2} aktive(r) Sponsor(en)",
  "Seu clube gera créditos mesmo quando você está fora (até {x3}h acumuladas). Fama, marketing, patrocinadores e jogadores famosos aumentam a renda.": "Dein Club erwirtschaftet Credits, auch wenn du nicht da bist (bis zu {x3} Std. angesammelt). Ruhm, Marketing, Sponsoren und berühmte Spieler erhöhen das Einkommen.",
