  "De onde vem a receita": "Woher das Einkommen kommt",
  "total {x2} cr./min": "gesamt {x2} Cr./Min.",
  "Níveis de fama": "Ruhmstufen",
  "A fama sobe com vitórias oficiais, promoção, boa colocação nas ligas, torneios internacionais, nível de marketing, astros no elenco e alguns patrocínios. Derrotas quase não tiram fama.": "Die Ruhm steigt durch offizielle Siege, Aufstieg, gute Ligaplatzierungen, internationale Turniere, Marketing-Stufe, Stars im Kader und einige Sponsorings. Niederlagen senken sie kaum.",
  "Próximo nível": "Nächste Stufe",
  "bônus de marketing {x3} → {x4}": "Marketing-Bonus {x3} → {x4}",
  "Melhorar · {x6} cr.": "Verbessern · {x6} Cr.",
