  "Com a sua receita de hoje rende cerca de +{x6} cr. no período ({x7} de {x8} cr.)": "Mit deinem heutigen Einkommen bringt sie etwa +{x6} Cr. im Zeitraum ({x7} von {x8} Cr.)",
