  "Em andamento · termina em {x1}": "Läuft · endet in {x1}",
  "· bônus de {x4} na receita base · {x5} contrato(s) de patrocínio simultâneo(s)": "· {x4} Bonus auf das Basiseinkommen · {x5} gleichzeitige(r) Sponsoring-Vertrag/Verträge",
