  "uma por vez": "eine nach der anderen",
  "Uma campanha multiplica": "Eine Kampagne vervielfacht",
  "toda a sua receita": "dein gesamtes Einkommen",
  "(clube, bônus comerciais e patrocinadores) durante o período. A estimativa de cada uma usa a sua receita atual por minuto. Depois que termina, ela fica em recarga.": "(Club, kommerzielle Boni und Sponsoren) während des Zeitraums. Die Schätzung jeder Kampagne nutzt dein aktuelles Einkommen pro Minute. Nach dem Ende ist sie in Abklingzeit.",
  "Marketing no nível máximo.": "Marketing auf maximaler Stufe.",
  "{x2} · +{x3} cr./min · termina em {x4}": "{x2} · +{x3} Cr./Min. · endet in {x4}",
  "Disponível": "Verfügbar",
  "Ativo": "Aktiv",
