  "Indisponível": "Nicht verfügbar",
  "Sem contratos livres: melhore o marketing.": "Keine freien Verträge: Verbessere dein Marketing.",
  "{x4} · +{x5} cr./min · {x6}h{x7}{x8}": "{x4} · +{x5} Cr./Min. · {x6} Std.{x7}{x8}",
  "Exige: fama {x9}, marketing {x10}{x11}{x12}. {x13}": "Voraussetzung: Ruhm {x9}, Marketing {x10}{x11}{x12}. {x13}",
  "· audiência +{x1}": "· Reichweite +{x1}",
  "· fama +{x1}": "· Ruhm +{x1}",
  ", divisão principal": ", Hauptdivision",
  ", {x1} titulares": ", {x1} Stammspieler",
  "Contratos ativos": "Aktive Verträge",
  "O custo é pago na assinatura. A renovação automática só acontece se houver saldo e o clube ainda cumprir os requisitos; nunca deixa o saldo negativo.": "Die Kosten werden bei Vertragsabschluss gezahlt. Die automatische Verlängerung erfolgt nur, wenn Guthaben vorhanden ist und der Club die Voraussetzungen noch erfüllt; das Guthaben wird nie negativ.",
  "Marcas": "Marken",
  "Nenhum patrocinador ativo. Contrate um abaixo para ganhar créditos fixos por minuto.": "Kein aktiver Sponsor. Verpflichte unten einen, um feste Credits pro Minute zu verdienen.",
  "Audiência": "Reichweite",
  "A audiência vem da": "Die Reichweite kommt von der",
  "fama dos jogadores": "Ruhm der Spieler",
  ": os cinco titulares contam inteiros e os melhores reservas contam {x2}. Cada jogador conta uma vez, e a conta é comprimida para que ter muitos astros não exploda a renda. Bônus atual:": ": Die fünf Stammspieler zählen voll und die besten Ersatzspieler zählen {x2}. Jeder Spieler zählt einmal, und die Berechnung wird gestaucht, damit viele Stars das Einkommen nicht explodieren lassen. Aktueller Bonus:",
  "na receita base (limite {x4} sem patrocínios). Contratar um astro aumenta a audiência; vendê-lo ou demiti-lo tira a contribuição dele. A fama do clube anterior de um jogador não passa para o seu.": "auf das Basiseinkommen (Limit {x4} ohne Sponsorings). Einen Star zu verpflichten erhöht die Reichweite; ihn zu verkaufen oder zu entlassen entfernt seinen Beitrag. Die Ruhm eines Spielers aus seinem früheren Club geht nicht auf deinen über.",
  "últimos {x1}": "letzte {x1}",
  "A receita passiva é lançada de forma consolidada (um lançamento por processamento), não segundo a segundo.": "Das passive Einkommen wird konsolidiert gebucht (eine Buchung pro Verarbeitung), nicht Sekunde für Sekunde.",
