  "Você entra numa partida com o nick errado. O narrador ri ao vivo e agora vocês são amigos.": "Du gehst mit dem falschen Nick in eine Partie. Der Caster lacht live und jetzt seid ihr Freunde.",
  "O departamento jurídico da {team} teve que refazer três documentos. Ninguém riu lá.": "Die Rechtsabteilung von {team} musste drei Dokumente neu machen. Dort hat niemand gelacht.",
