  "Pick padrão, jogo limpo, vitória. O técnico guardou a ideia \"para o Mundial\".": "Standard-Pick, sauberes Spiel, Sieg. Der Trainer hob sich die Idee „für die Weltmeisterschaft“ auf.",
  "Vocês perderam do jeito normal, e o técnico passou a semana dizendo \"eu avisei\".": "Ihr habt auf normale Weise verloren, und der Trainer sagte die ganze Woche „Ich hab’s euch gesagt“.",
  "O energético novo do patrocinador": "Das neue Energy-Getränk des Sponsors",
  "O patrocinador lançou um sabor \"Barão Roxo\" e quer você bebendo ao vivo na câmera. O gosto lembra xarope de tosse com chiclete.": "Der Sponsor hat eine Sorte „Purpurner Baron“ herausgebracht und will, dass du sie live vor der Kamera trinkst. Sie schmeckt nach Hustensaft mit Kaugummi.",
  "Beber e elogiar com a cara mais séria do mundo": "Trinken und es mit dem ernstesten Gesicht der Welt loben",
  "patrocinador feliz": "Sponsor zufrieden",
  "careta viraliza": "Grimasse geht viral",
  "\"Refrescante, com notas de vitória.\" O patrocinador renovou por mais um ano.": "„Erfrischend, mit Noten von Sieg.“ Der Sponsor hat um ein weiteres Jahr verlängert.",
  "Sua careta durou 0,3 segundos, mas o suficiente para virar figurinha no Brasil inteiro.": "Deine Grimasse dauerte 0,3 Sekunden, aber das reichte, um in ganz Brasilien zum Sticker zu werden.",
  "Sugerir um sabor novo para a marca": "Der Marke eine neue Sorte vorschlagen",
  "sabor com seu nome": "Sorte mit deinem Namen",
  "marca ignora": "Marke ignoriert es",
  "O sabor \"Pentakill de Limão\" com a sua cara na lata vende muito.": "Die Sorte „Zitronen-Pentakill“ mit deinem Gesicht auf der Dose verkauft sich hervorragend.",
  "A marca respondeu com um \"vamos avaliar\" que nunca foi avaliado.": "Die Marke antwortete mit einem „Wir prüfen das“, das nie geprüft wurde.",
  "Roubaram o Barão no seu smite": "Sie haben den Baron mit deinem Smite gestohlen",
  "Barão com 800 de vida, seu smite tira 1200. O jungle deles pula do nada, dá smite antes e rouba. O replay está em todas as redes.": "Baron mit 800 Leben, dein Smite macht 1200. Ihr Jungler springt aus dem Nichts, smitet zuerst und stiehlt ihn. Das Replay ist in allen Netzwerken.",
  "Treinar timing de smite até sonhar com ele": "Smite-Timing trainieren, bis du davon träumst",
  "nunca mais perde um": "verpasst keinen mehr",
  "fica paranoico": "wird paranoid",
  "Uma semana na ferramenta de treino. No jogo seguinte, você rouba um dragão ancião de volta.": "Eine Woche im Übungsmodus. Im nächsten Spiel stiehlst du einen Uralten Drachen zurück.",
  "Agora você dá smite cedo demais de nervoso. O técnico pediu calma.": "Jetzt smitest du aus Nervosität zu früh. Der Trainer bat dich um Ruhe.",
  "Postar \"foi a sorte dele\" nas redes": "„Das war nur sein Glück“ in den sozialen Netzwerken posten",
  "comunidade concorda": "Community stimmt zu",
  "vira chacota": "wird zum Gespött",
  "Até o jungle rival admitiu que foi sorte. Vocês viraram amigos de SoloQ.": "Sogar der gegnerische Jungler gab zu, dass es Glück war. Ihr seid Solo-Queue-Freunde geworden.",
  "A comunidade montou uma compilação de todos os seus smites errados. São muitos.": "Die Community hat eine Zusammenstellung all deiner verpassten Smites erstellt. Es sind viele.",
  "COMPANHEIROS": "MITSPIELER",
  "Roubaram seu pentakill": "Sie haben dir dein Pentakill gestohlen",
  "Você fez quatro abates na luta final e o quinto estava com 30 de vida. Seu suporte deu o último golpe e ficou com o abate.": "Du hast im letzten Kampf vier Kills geholt und der fünfte hatte 30 Leben. Dein Support hat den letzten Schlag gesetzt und den Kill bekommen.",
  "Rir e transformar em piada interna": "Lachen und einen internen Witz daraus machen",
  "time mais unido": "Team enger verbunden",
  "piada cansa": "der Witz nutzt sich ab",
  "O time imprimiu uma foto do placar e pendurou na gaming house. Vocês nunca estiveram tão unidos.": "Das Team hat ein Foto der Anzeigetafel ausgedruckt und im Gaming-House aufgehängt. Ihr wart noch nie so verbunden.",
  "A piada foi repetida tantas vezes que perdeu a graça. Principalmente para você.": "Der Witz wurde so oft wiederholt, dass er nicht mehr lustig war. Vor allem für dich.",
  "Exigir que ele pague o jantar da equipe": "Verlangen, dass er das Teamessen bezahlt",
  "rodízio de graça": "kostenloses All-you-can-eat",
  "discussão sobre o preço": "Streit über den Preis",
  "Rodízio completo por conta dele. Ninguém mais rouba abate de ninguém.": "Ein komplettes All-you-can-eat auf seine Kosten. Niemand klaut mehr jemandem Kills.",
  "Ele escolheu o restaurante mais barato da cidade. Ninguém comeu direito.": "Er wählte das billigste Restaurant der Stadt. Niemand hat richtig gegessen.",
  "Flash no D ou no F?": "Flash auf D oder auf F?",
  "O time novo inteiro usa o Flash numa tecla diferente da sua. O técnico quer padronizar \"para facilitar as calls\".": "Das gesamte neue Team benutzt Flash auf einer anderen Taste als du. Der Trainer will es vereinheitlichen, „um die Calls zu erleichtern“.",
  "Trocar a tecla do Flash": "Die Flash-Taste wechseln",
  "adaptação rápida": "schnelle Anpassung",
  "Flash errado em jogo oficial": "falsches Flash im offiziellen Spiel",
  "Duas semanas de sofrimento e pronto: agora você nem lembra que era diferente.": "Zwei Wochen Leiden und das war’s: Jetzt erinnerst du dich nicht einmal mehr, dass es anders war.",
  "Em jogo oficial, você usou Teleporte em vez de Flash para fugir. O narrador não conseguiu parar de rir.": "In einem offiziellen Spiel hast du zur Flucht Teleport statt Flash benutzt. Der Caster konnte nicht aufhören zu lachen.",
  "Defender sua tecla com uma apresentação de slides": "Deine Taste mit einer Präsentation verteidigen",
  "convence o time": "überzeugt das Team",
  "slides viram meme": "Folien werden zum Meme",
  "14 slides e um gráfico de pizza depois, o técnico cedeu. Você mantém a sua tecla.": "Nach 14 Folien und einem Tortendiagramm gab der Trainer nach. Du behältst deine Taste.",
  "Os slides vazaram e viraram o assunto da semana no cenário.": "Die Folien sind durchgesickert und waren das Gesprächsthema der Szene in dieser Woche.",
  "FAMÍLIA": "FAMILIE",
  "Sua avó virou a maior fã do cenário": "Deine Oma ist zum größten Fan der Szene geworden",
  "Ela aprendeu a assistir às partidas, criou conta no X e comenta \"esse é meu neto\" em todo post {doLeague}.": "Sie hat gelernt, die Partien zu schauen, ein Konto auf X angelegt und kommentiert „Das ist mein Enkel“ unter jedem Beitrag {doLeague}.",
  "Levar ela para assistir na arena": "Sie mit in die Arena nehmen",
