  "A câmera a achou na arena com uma placa escrita \"{nick} MEU NETO\". A arena inteira aplaudiu.": "Die Kamera fand sie in der Arena mit einem Schild „{nick} MEIN ENKEL“. Die ganze Arena applaudierte.",
  "Ela discutiu com a torcida rival sobre o draft. Na verdade, ela estava certa.": "Sie hat mit den gegnerischen Fans über den Draft diskutiert. Tatsächlich hatte sie recht.",
