  "Ela entendeu e agora só manda mensagem no privado com dicas de posicionamento.": "Sie hat es verstanden und schickt jetzt nur noch private Nachrichten mit Positionierungstipps.",
  "Ela criou uma conta secundária. Agora são duas avós comentando em tudo.": "Sie hat ein Zweitkonto erstellt. Jetzt kommentieren zwei Omas alles.",
