  "Um jogador aleatório cai no seu time em toda partida e escolhe um suporte no mid. Já são cinco derrotas seguidas.": "Ein zufälliger Spieler landet in jeder Partie in deinem Team und wählt einen Support auf Mid. Das sind schon fünf Niederlagen in Folge.",
