  "Todo mundo dormiu no palco. Literalmente: a câmera pegou o top cochilando no draft.": "Alle sind auf der Bühne eingeschlafen. Buchstäblich: Die Kamera hat den Toplaner beim Dösen im Draft erwischt.",
